<script setup lang="ts">
import { computed } from 'vue'
import { Search, SlidersHorizontal, RotateCcw } from 'lucide-vue-next'
import { createDefaultMaintenanceFilters, hasMaintenanceFilters, MAINTENANCE_SORT_OPTIONS, MAINTENANCE_TIMING_OPTIONS, type MaintenanceFilters } from './disclosureMaintenance'
import type { GridDisclosureCategory } from './types'

const props = withDefaults(defineProps<{ modelValue: MaintenanceFilters; category?: '' | GridDisclosureCategory; categories?: GridDisclosureCategory[]; windowLabel: string; generic?: boolean }>(), { category: '', categories: () => ['maintenance', 'outage'], generic: false })
const emit = defineEmits<{ 'update:modelValue': [value: MaintenanceFilters]; 'update:category': [value: '' | GridDisclosureCategory]; clear: [] }>()
const categoryLabels: Record<GridDisclosureCategory, string> = { maintenance: '检修计划', outage: '非计划停运', intervention: '人工干预', congestion: '断面阻塞', constraint: '输电约束' }
const timingOptions = computed(() => props.generic ? MAINTENANCE_TIMING_OPTIONS.map(option => ({ ...option, label: option.value === 'starts-in-window' ? '窗口内开始' : option.value === 'ends-in-window' ? '窗口内结束' : option.label })) : MAINTENANCE_TIMING_OPTIONS)
const sortOptions = computed(() => props.generic ? MAINTENANCE_SORT_OPTIONS.map(option => ({ ...option, label: option.value === 'start-asc' ? '开始时间：早 → 晚' : option.value === 'end-asc' ? '结束时间：早 → 晚' : option.label })) : MAINTENANCE_SORT_OPTIONS)
const active = computed(() => hasMaintenanceFilters(props.modelValue) || Boolean(props.category))
function update<K extends keyof MaintenanceFilters>(key: K, value: MaintenanceFilters[K]) { emit('update:modelValue', { ...props.modelValue, [key]: value }) }
function clear() { emit('update:modelValue', createDefaultMaintenanceFilters()); emit('update:category', ''); emit('clear') }
</script>

<template>
  <section class="maintenance-tools" :data-testid="generic ? 'disclosure-tools' : 'maintenance-tools'" :aria-label="generic ? '披露筛选' : '检修停运专业筛选'">
    <header><span><SlidersHorizontal :size="16" />{{ generic ? '披露筛选' : '检修与停运筛选' }}</span><button type="button" class="clear" :disabled="!active" @click="clear"><RotateCcw :size="13" />{{ generic ? '清空筛选' : '清空专业筛选' }}</button></header>
    <p class="window-label">查询窗口：{{ windowLabel }} · 时间关系均相对此窗口</p>
    <div class="search-fields"><label><span><Search :size="14" />{{ generic ? '对象 / 设备' : '设备 / 电厂' }}</span><input :value="modelValue.equipmentKeyword" :aria-label="generic ? '搜索披露对象' : '搜索检修设备或电厂'" type="search" :placeholder="generic ? '输入电厂、设备、线路或断面名称' : '输入电厂、机组或线路名称'" maxlength="200" @input="update('equipmentKeyword', ($event.target as HTMLInputElement).value)" /></label><label><span><Search :size="14" />原因 / 摘要</span><input :value="modelValue.reasonKeyword" :aria-label="generic ? '搜索披露原因或摘要' : '搜索检修停运原因'" type="search" :placeholder="generic ? '输入原因或摘要关键词' : '输入检修项目、故障、原因或摘要关键词'" maxlength="200" @input="update('reasonKeyword', ($event.target as HTMLInputElement).value)" /></label></div>
    <div class="filters-row"><div class="categories" role="group" :aria-label="generic ? '披露类别' : '检修停运类别'"><button type="button" :aria-pressed="category === ''" @click="emit('update:category', '')">全部</button><button v-for="item in categories" :key="item" type="button" :aria-pressed="category === item" @click="emit('update:category', item)">{{ categoryLabels[item] }}</button></div><label>{{ generic ? '披露时间关系' : '时间关系' }}<select :value="modelValue.timingFilter" :aria-label="generic ? '披露时间关系' : '检修停运时间关系'" @change="update('timingFilter', ($event.target as HTMLSelectElement).value as MaintenanceFilters['timingFilter'])"><option v-for="option in timingOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>{{ generic ? '披露排序' : '排序' }}<select :value="modelValue.sort" :aria-label="generic ? '披露排序' : '检修停运排序'" @change="update('sort', ($event.target as HTMLSelectElement).value as MaintenanceFilters['sort'])"><option v-for="option in sortOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label></div>
  </section>
</template>

<style scoped>
.maintenance-tools{min-width:0;padding:16px;border-bottom:1px solid var(--line);background:var(--panel-sub);color:var(--text)}header,header>span,.clear,.categories,.filters-row,.search-fields label>span{display:flex;align-items:center;gap:7px}header{justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:var(--font-sm);font-weight:600}.clear{font-size:var(--font-xs);border:0;color:var(--primary);background:transparent;padding:4px 0;cursor:pointer}.clear:disabled{color:var(--muted);opacity:.6;cursor:default}.window-label{margin:9px 0 14px;color:var(--muted);font-size:var(--font-xs);line-height:1.6;overflow-wrap:anywhere}.search-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}.search-fields label{min-width:0;display:grid;gap:7px;font-size:var(--font-xs);color:var(--text-soft)}input,select{box-sizing:border-box;min-width:0;max-width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--text);font:inherit;font-size:var(--font-sm)}input{width:100%}.filters-row{flex-wrap:wrap;gap:12px}.filters-row>label{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:var(--font-xs);min-width:0}.categories{gap:5px;flex-wrap:wrap}.categories button{padding:7px 10px;border:1px solid var(--line);background:var(--panel);color:var(--text-soft);border-radius:6px;font-size:var(--font-xs);cursor:pointer}.categories button[aria-pressed=true]{color:var(--primary);background:var(--primary-tint);border-color:var(--primary-tint-border)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--primary);outline-offset:3px}@media(max-width:700px){.maintenance-tools{padding:12px}.search-fields{grid-template-columns:minmax(0,1fr)}.filters-row{align-items:stretch}.categories{flex-basis:100%}.filters-row>label{flex:1;display:grid;align-content:start;gap:6px}.filters-row select{width:100%}}
</style>
